    {
        "current": {
            "client-1": {
                "access_token": "some-token",
                ...
                "username": "user"
            }
        },
        "sessions": {
            "sd2e": {
                "admin": {
                    "client-1": {
                        "access_token": "other-token",
                        ...
                        "username": "user"
                    },
                    "client-2": {
                        "access_token": "some-token",
