    @classmethod
    def set_session(cls, session):
        """
        :type session: scoped_session | Session
        """
        # Set the _session attribute on the instance
        def wrapper(inst):
            inst._session = session
        # Iterate over all subclasses to set the _session attribute
        for subclass in cls.__subclasses__():
            wrapper(subclass)
            for subsubclass in subclass.__subclasses__():
                wrapper(subsubclass)
        # Set the _session attribute on the current class
        wrapper(cls)

    @property
    def session(self):
        """
